if (this.id != this._cssName?.basis) {
  // Clear the old names.
  if (this._cssName) {
    this.parentNode.style.removeProperty(this._cssName.width);
    this.parentNode.style.removeProperty(this._cssName.height);
  }
  this._cssName = {
    basis: this.id,
    height: `--${this.id}-height`,
    width: `--${this.id}-width`,
  };
